const body = $input.item.json.body || $input.item.json;
if (!body.script) throw new Error('缺少脚本');
const lines = body.script.split('\n').filter(l=>l.trim());
const ctaLine = lines.find(l=>/CTA[：:]/.test(l)) || '';
const spoken = body.spoken_line || ctaLine.replace(/^CTA[：:]\s*/,'') || '现在入手吧';
return [{ json: {
  script: body.script,
  spoken_line: spoken,
  creator_preference: body.creator_preference || '25岁亚洲女性，短黑发，自然妆，亲切真实',
  product_image_url: body.product_image_url || '',
  language: body.language || '中文'
}}];

const d = $input.item.json;
const isCN = d.language === '中文';
const task = {
  video_task_id: 'vt-'+Date.now(),
  spoken_line: d.spoken_line,
  creator_preference: d.creator_preference,
  language: d.language,
  duration_seconds: 8,
  aspect_ratio: '9:16',
  model: isCN?'Seedance 2.0 Fast':'Veo 3.1 Fast',
  image_prompt: `UGC key image: ${d.creator_preference}, holding product naturally, soft daylight, vertical 9:16`,
  video_prompt: `UGC talking-head: ${d.creator_preference}, speaking "${d.spoken_line}" to camera, real background, natural gestures, ${isCN?'Chinese e-commerce vibe':'Western UGC'}`
};
return [{ json: { ok:true, video_task:task } }];
